test('冒烟:基本转义', () => {
  assert.equal(escapeHtml('<b>'), '&lt;b&gt;');
});

test('四类字符混合出现时全部转义', () => {
  assert.equal(escapeHtml('&<>"'), '&amp;&lt;&gt;&quot;');
  assert.equal(
    escapeHtml('<a href="x">Tom & Jerry</a>'),
    '&lt;a href=&quot;x&quot;&gt;Tom &amp; Jerry&lt;/a&gt;'
  );
});

test('不含特殊字符的普通文本(含中文)保持不变', () => {
  assert.equal(escapeHtml('Hello, world!'), 'Hello, world!');
  assert.equal(escapeHtml('你好,世界'), '你好,世界');
  assert.equal(escapeHtml('普通文本 123 abc'), '普通文本 123 abc');
});

test('数字入参先转 String 再转义', () => {
  assert.equal(escapeHtml(123), '123');
  assert.equal(escapeHtml(0), '0');
  assert.equal(escapeHtml(-45), '-45');
});
